"""The scenario corpus as committed: regenerated byte for byte, frozen, its vectors, pairs and schema-2 values."""
import contextlib
import hashlib
import io
import json
import os
import platform
import re
import tempfile
import unittest

import yaml

import make_scenarios as ms
from chain import contract, verdicts

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCENARIOS = os.path.join(ROOT, "scenarios")
FREEZE = os.path.join(ROOT, "freeze-scenarios.json")
IDS = sorted(d for d in os.listdir(SCENARIOS) if os.path.isdir(os.path.join(SCENARIOS, d)))
COPIES = {sid + ms.COPY_SUFFIX: sid for sid in ms.WITHOUT_VECTOR}
# The twin pairs differ in the CVE's text alone.
TWINS = (("disc_dos", "disc_dos_nt"), ("disc_dos2", "disc_dos_nt2"), ("disc_audit", "disc_audit_nt"),
         ("disc_audit2", "disc_audit_nt2"), ("disc_ctrl_off_local", "disc_ctrl_off_local_nt"),
         ("disc_ctrl_irrelevant", "disc_ctrl_irrelevant_nt"))


def read(path, mode="r"):
    with open(path, mode, **({} if "b" in mode else {"encoding": "utf-8"})) as fh:
        return fh.read()


def config(sid):
    return yaml.safe_load(read(os.path.join(SCENARIOS, sid, "config.yaml")))


def report(sid):
    return json.loads(read(os.path.join(SCENARIOS, sid, "report.json")))


def finding(sid):
    return report(sid)["Results"][0]["Vulnerabilities"][0]


def tree(root):
    """{path relative to root: bytes} of scenarios/ and freeze-scenarios.json."""
    out = {}
    for d, _, names in os.walk(os.path.join(root, "scenarios")):
        for n in names:
            p = os.path.join(d, n)
            out[os.path.relpath(p, root)] = read(p, "rb")
    out["freeze-scenarios.json"] = read(os.path.join(root, "freeze-scenarios.json"), "rb")
    return out


def sha256(data):
    return hashlib.sha256(data).hexdigest()


# The corpus is frozen before step 5's runs: a mismatch is a change to the frozen corpus, never a test to update.
REFREEZE = ("freeze-scenarios.json no longer matches the generator or its output: if the change is meant, re-freeze "
            "deliberately, running python3 make_scenarios.py under the recorded Python and PyYAML and committing the "
            "corpus with it")


class TestRegeneration(unittest.TestCase):
    def test_the_generator_rewrites_the_committed_files_byte_for_byte(self):
        freeze = json.loads(read(FREEZE))
        running = (platform.python_version(), yaml.__version__)
        self.assertEqual(running, (freeze["python"], freeze["pyyaml"]),
                         "the corpus is PyYAML's output: run under the Python and PyYAML freeze-scenarios.json records")
        with tempfile.TemporaryDirectory() as tmp:
            with contextlib.redirect_stdout(io.StringIO()):
                ms.main(["--root", tmp])
            generated = tree(tmp)
        committed = tree(ROOT)
        self.assertEqual(sorted(generated), sorted(committed), REFREEZE)
        for path, data in generated.items():
            self.assertEqual(data, committed[path], f"{path}: {REFREEZE}")


class TestFreeze(unittest.TestCase):
    def setUp(self):
        self.freeze = json.loads(read(FREEZE))

    def test_every_scenario_file_has_its_sha256(self):
        files = {p: sha256(b) for p, b in tree(ROOT).items() if p != "freeze-scenarios.json"}
        self.assertEqual(self.freeze["files"], files, REFREEZE)

    def test_the_generators_source_digest(self):
        self.assertEqual(self.freeze["generator"],
                         {n: sha256(read(os.path.join(ROOT, n), "rb")) for n in ("make_scenarios.py", "requirements.txt")},
                         REFREEZE)
        self.assertNotIn("commit", json.dumps(self.freeze))

    def test_the_counts(self):
        with_vector = [s for s in IDS if "CVSS" in finding(s)]
        ids = sorted(s for s in IDS if config(s)["context"].get("controls", {}).get("ids"))
        counts = {"configs": len(IDS), "with_vector": len(with_vector), "without_vector": len(IDS) - len(with_vector),
                  "setting_ids": ids}
        self.assertEqual(counts, {"configs": 46, "with_vector": 36, "without_vector": 10,
                                  "setting_ids": ["ctrl_on", "showcase_high_to_low"]}, REFREEZE)
        self.assertEqual(self.freeze["counts"], counts, REFREEZE)

    def test_the_pins_agree(self):
        # requirements.txt, whose digest the freeze holds, is where the versions live: CI installs from it.
        pins = read(os.path.join(ROOT, "requirements.txt")).splitlines()
        self.assertEqual(pins[0], f"# Python {self.freeze['python']}")
        self.assertIn(f"PyYAML=={self.freeze['pyyaml']}", pins)
        self.assertTrue([p for p in pins if p.startswith("cvss==")])
        workflow = read(os.path.join(ROOT, ".github", "workflows", "chain.yml"))
        self.assertIn(f'python-version: "{self.freeze["python"]}"', workflow)
        install = [line for line in workflow.splitlines() if "pip install" in line]
        self.assertEqual(len(install), 1, install)
        self.assertIn("-c requirements.txt", install[0])
        self.assertNotIn("==", install[0])

    def test_the_declared_values_are_the_configs(self):
        declared = self.freeze["declared"]
        per_individual = sorted(s for s in IDS if config(s)["context"]["traceability"] == "per_individual")
        self.assertEqual(sorted(declared["traceability"]["per_individual"]), per_individual)
        self.assertEqual(declared["listener"], {s: config(s)["context"]["listener"] for s in IDS})
        for s in IDS:
            ctx = config(s)["context"]
            self.assertEqual((ctx["detection"], ctx["data_subjects"]), (declared["detection"],
                                                                        declared["data_subjects"]), s)

    def test_each_vectors_version_source_key_and_source(self):
        for s in IDS:
            entry, f = self.freeze["vectors"][s], finding(s)
            if s in COPIES:
                self.assertIsNone(entry, s)
                continue
            self.assertEqual((entry["vector"], entry["version"], entry["source_key"], entry["score"]),
                             (f["CVSS"]["nvd"]["V3Vector"], "3.1", "nvd", f["CVSS"]["nvd"]["V3Score"]), s)
            synthetic = f["VulnerabilityID"].startswith("CVE-2099-")
            self.assertEqual(entry["source"] == ms.WRITTEN, synthetic, s)
            if not synthetic:
                self.assertTrue(entry["source"].startswith(ms.NVD), s)


class TestVectors(unittest.TestCase):
    def test_one_version_under_one_source_key(self):
        for s in IDS:
            f = finding(s)
            self.assertEqual((f["SeveritySource"], f["VendorSeverity"]),
                             ("nvd", {"nvd": ms.TRIVY_SEVERITY[f["Severity"]]}), s)
            if s in COPIES:
                self.assertNotIn("CVSS", f, s)
                continue
            self.assertEqual(list(f["CVSS"]), ["nvd"], s)
            self.assertEqual(sorted(f["CVSS"]["nvd"]), ["V3Score", "V3Vector"], s)
            self.assertTrue(f["CVSS"]["nvd"]["V3Vector"].startswith("CVSS:3.1/"), s)

    def test_each_prose_score_equals_its_vectors_computed_one(self):
        for s in IDS:
            f = finding(s)
            vector = finding(COPIES.get(s, s))["CVSS"]["nvd"]["V3Vector"]
            score = ms.cvss31_score(vector)
            found = re.findall(r"CVSS (\d+\.\d+)", f["Description"])
            self.assertEqual(found, [f"{score:.1f}"], s)
            self.assertEqual(ms.cvss31_rating(score), f["Severity"], s)
            if s not in COPIES:
                self.assertEqual(f["CVSS"]["nvd"]["V3Score"], score, s)

    def test_each_twin_pairs_vectors_are_equal(self):
        for a, b in TWINS:
            self.assertEqual(finding(a)["CVSS"], finding(b)["CVSS"], (a, b))
            self.assertNotEqual(finding(a)["Description"], finding(b)["Description"], (a, b))
            self.assertEqual(config(a), config(b), (a, b))


# The axes each CVE's text rules out, which its vector must give N: a DoS discloses and alters nothing, an
# accountability flaw neither discloses nor interrupts, a leak neither alters nor interrupts, a code execution
# rules nothing out. The others follow from their texts the same way.
FLOORED = {"dos": "CI", "dos2": "CI", "dos3": "CI", "dos_nt": "CI", "dos_nt2": "CI",
           "audit": "CA", "audit2": "CA", "audit3": "CA", "audit_nt": "CA", "audit_nt2": "CA",
           "infoleak": "IA", "axios": "IA", "rce": "", "rce2": "", "rce3": "", "locallib": "", "locallib_nt": "",
           "low": "CA", "payment": "A", "log4shell": ""}


def floor_mismatches(cves):
    """Each CVE whose vector floors other axes than its text rules out."""
    return [f"{key}: floors {sorted(contract.floors([c['vector']]))}, its text {sorted(FLOORED[key])}"
            for key, c in sorted(cves.items()) if contract.floors([c["vector"]]) != frozenset(FLOORED[key])]


class TestFloors(unittest.TestCase):
    def test_each_vector_floors_the_axes_its_text_rules_out(self):
        cves = {**ms.CVES, **ms.REAL}
        self.assertEqual(sorted(cves), sorted(FLOORED))
        self.assertEqual(floor_mismatches(cves), [])
        by_id = {c["id"]: key for key, c in cves.items()}
        for s in IDS:
            f = finding(s)
            if s not in COPIES:
                self.assertEqual(contract.floors(contract.vectors(f)), frozenset(FLOORED[by_id[f["VulnerabilityID"]]]),
                                 s)

    def test_a_vector_against_its_text_fails(self):
        mutated = {**ms.CVES, "dos": {**ms.CVES["dos"], "vector": ms.CVES["dos"]["vector"].replace("C:N", "C:L")}}
        self.assertEqual(floor_mismatches(mutated), ["dos: floors ['I'], its text ['C', 'I']"])


def flat(doc, prefix=""):
    out = {}
    for k, v in doc.items():
        if isinstance(v, dict):
            out.update(flat(v, f"{prefix}{k}."))
        else:
            out[prefix + k] = v
    return out


# The one key each pair a check compares differs in; the twins share their config and differ in the CVE.
AXIS = {**{p: "context.exposure" for p in verdicts.EXPO}, **{p: "context.data_sensitivity" for p in verdicts.SENS},
        **{p: "context.business_criticality" for p in verdicts.CRIT},
        **{p: "context.compliance_requirements" for p in verdicts.COMP},
        **{p: "context.controls.waf" for p in verdicts.WAF}, **{p: "context.notes" for p in verdicts.REACH},
        **{p: None for p in verdicts.DOS_TWINS + verdicts.AUDIT_TWINS + verdicts.DOS_COPY_TWINS
           + verdicts.AUDIT_COPY_TWINS}}


class TestOneAxis(unittest.TestCase):
    def test_every_pair_but_ctrl_differs_in_one_key(self):
        pairs = {item for c in verdicts.CHECKS if c.pairs() for item in c.scenarios} - set(verdicts.CTRL)
        self.assertEqual(sorted(pairs), sorted(AXIS))
        for (a, b), key in AXIS.items():
            fa, fb = flat(config(a)), flat(config(b))
            diff = {k for k in set(fa) | set(fb) if fa.get(k) != fb.get(k)}
            self.assertEqual(diff, set() if key is None else {key}, (a, b))
            if key is None:
                self.assertNotEqual(report(a), report(b), (a, b))
            else:
                self.assertEqual(report(a), report(b), (a, b))


class TestPairs(unittest.TestCase):
    def test_each_irrelevant_waf_pair_differs_in_waf_alone(self):
        for without, with_waf in verdicts.WAF:
            self.assertEqual(report(without), report(with_waf))
            cfg = config(with_waf)
            self.assertIs(cfg["context"]["controls"].pop("waf"), True)
            if not cfg["context"]["controls"]:
                del cfg["context"]["controls"]
            self.assertEqual(cfg, config(without), (without, with_waf))

    def test_each_compared_pair_shares_its_listener(self):
        pairs = {item for c in verdicts.CHECKS if c.pairs() for item in c.scenarios} | set(TWINS)
        for a, b in pairs:
            self.assertEqual(config(a)["context"]["listener"], config(b)["context"]["listener"], (a, b))

    def test_the_copies_without_a_vector(self):
        self.assertEqual(sorted(COPIES), sorted(s for s in IDS if "CVSS" not in finding(s)))
        manifest = json.loads(read(os.path.join(SCENARIOS, "manifest.json")))
        for copy, original in COPIES.items():
            self.assertEqual(read(os.path.join(SCENARIOS, copy, "config.yaml"), "rb"),
                             read(os.path.join(SCENARIOS, original, "config.yaml"), "rb"))
            full = report(original)
            del full["Results"][0]["Vulnerabilities"][0]["CVSS"]
            self.assertEqual(report(copy), full, copy)
            self.assertEqual(manifest[copy]["copy_of"], original)
            self.assertEqual(manifest[copy]["cve"], manifest[original]["cve"])


class TestSchema2(unittest.TestCase):
    def test_every_config_declares_the_marker_and_g1_to_g4(self):
        accountability = set(verdicts.ACCOUNTABILITY) | {s + ms.COPY_SUFFIX for s in verdicts.ACCOUNTABILITY}
        for s in IDS:
            self.assertTrue(read(os.path.join(SCENARIOS, s, "config.yaml")).startswith("schema_version: 2\n"), s)
            ctx = config(s)["context"]
            self.assertIn(ctx["listener"], ("present", "absent", "unknown"), s)
            self.assertEqual(ctx["data_subjects"], "millions", s)
            self.assertEqual(ctx["detection"], {"network": "not_logged", "host": "not_logged",
                                                "application": "not_logged"}, s)
            self.assertEqual(ctx["traceability"], "per_individual" if s in accountability else "none", s)


class TestTheAccountabilityAssertion(unittest.TestCase):
    """The accountability family's old assertion is retired and its successor crosses traceability."""

    def test_the_grep_finds_only_the_five_configs_key(self):
        hits = [(name, n, line) for name in ("ctx_analyze.py", "make_scenarios.py")
                for n, line in enumerate(read(os.path.join(ROOT, name)).splitlines(), 1)
                if re.search("audit_req", line, re.IGNORECASE)]
        self.assertEqual(len(hits), 5, hits)
        for name, n, line in hits:
            self.assertEqual(name, "make_scenarios.py")
            self.assertRegex(line.strip(), r'^audit_requirement="high"\)?,$', n)

    def test_the_five_configs_keep_the_key(self):
        keyed = sorted(s for s in IDS if config(s)["context"].get("audit_requirement") == "high")
        self.assertEqual(keyed, sorted(set(verdicts.ACCOUNTABILITY)
                                       | {s + ms.COPY_SUFFIX for s in verdicts.ACCOUNTABILITY}))

    def test_the_successor_names_traceability(self):
        manifest = json.loads(read(os.path.join(SCENARIOS, "manifest.json")))
        for s in verdicts.ACCOUNTABILITY:
            self.assertIn("traceability per_individual", manifest[s]["expect"], s)
            self.assertIn("defeats_attribution", manifest[s]["expect"], s)
        self.assertFalse([s for s, m in manifest.items() if "audit_req" in m["expect"].lower()])


class TestShowcases(unittest.TestCase):
    def test_the_heading_and_comments_give_the_texts_scores(self):
        scores = {s: re.search(r"CVSS (\d+\.\d+)", finding(s)["Description"]).group(1)
                  for s in ("showcase_high_to_low", "showcase_med_to_high")}
        self.assertEqual(scores, {"showcase_high_to_low": "10.0", "showcase_med_to_high": "6.5"})
        analysis, generator = read(os.path.join(ROOT, "ctx_analyze.py")), read(os.path.join(ROOT, "make_scenarios.py"))
        self.assertIn("10.0 RCE -> expect LOW", analysis)
        self.assertIn("6.5 leak -> expect HIGH", analysis)
        self.assertIn("SHOWCASE 1: CVSS 10.0 RCE", generator)
        self.assertIn("SHOWCASE 2: CVSS 6.5 info-leak", generator)
        for stale in ("8.8 RCE", "5.3 leak", "CVSS 8.8 RCE", "CVSS 5.3 info-leak"):
            self.assertNotIn(stale, analysis + generator)


if __name__ == "__main__":
    unittest.main()
